corrected_code:
const express = require('express');
const { HTTP } = require('cloudevents');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();
app.use(express.json({ type: ['application/json', 'application/cloudevents+json'] }));

app.post('/api/webhooks/cloudevents/crm', async (req, res) => {
  const webhookSecret = req.headers['x-crm-webhook-token'];
  if (!webhookSecret) {
    return res.status(401).json({ error: 'Webhook authorization token missing' });
  }

  const endpointConfig = await prisma.crmWebhookConfig.findUnique({
    where: { token: webhookSecret }
  });

  if (!endpointConfig) {
    return res.status(403).json({ error: 'Invalid webhook token' });
  }

  const event = HTTP.toEvent({ headers: req.headers, body: req.body });

  if (event.type === 'com.salesforce.contact.deleted') {
    const { contactId } = event.data;

    // Enforce deletion only within the organization bound to the webhook secret
    const contact = await prisma.crmContact.findFirst({
      where: { id: contactId, organizationId: endpointConfig.organizationId }
    });

    if (!contact) {
      return res.status(404).json({ error: 'Contact not found in caller organization' });
    }

    await prisma.crmContact.delete({
      where: { id: contactId }
    });
  }

  res.status(200).json({ processed: true });
});

app.listen(9009);
